1	import { NextRequest, NextResponse } from "next/server";
2	import { paypalConfigured, verifyPayPalWebhookSignature, getPayPalOrder, vaultInfoFromCapture } from "@/lib/paypal";
3	import { fulfilExternalPayment } from "@/lib/fulfil-checkout";
4	import { db } from "@/lib/db";
5	
6	/**
7	 * PayPal's reliable backstop, the same role app/api/stripe/webhook/route.ts plays
8	 * for Stripe: the client-driven capture (lib/actions-payment-providers.ts's
9	 * `captureExternalPayPalOrder`, called from the wizard's `onApprove`) may never
10	 * run at all if the customer closes the tab right after approving — this is the
11	 * ONLY guaranteed-to-fire signal in that case.
12	 *
13	 * Signature verification is PayPal's own server-to-server
14	 * `/v1/notifications/verify-webhook-signature` call (see lib/paypal.ts) — no local
15	 * certificate-chain validation to get subtly wrong. A webhook that cannot be
16	 * PROVEN authentic is rejected with 400, never processed "just in case".
17	 *
18	 * Idempotent the same way the Stripe webhook is: `fulfilExternalPayment` claims
19	 * a `FulfilledSession` row keyed `paypal:<orderId>` before doing any provisioning,
20	 * so this racing the client-driven capture (or PayPal redelivering the same
21	 * event) is always safe.
22	 */
23	export async function POST(req: NextRequest) {
24	  if (!paypalConfigured()) {
25	    return NextResponse.json({ error: "not configured" }, { status: 400 });
26	  }
27	  const raw = await req.text();
28	
29	  const verified = await verifyPayPalWebhookSignature(req.headers, raw);
30	  if (!verified) {
31	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
32	  }
33	
34	  let event: { event_type?: string; resource?: { id?: string; supplementary_data?: { related_ids?: { order_id?: string } } } };
35	  try {
36	    event = JSON.parse(raw);
37	  } catch {
38	    return NextResponse.json({ error: "invalid payload" }, { status: 400 });
39	  }
40	
41	  // We only need to act on a completed capture. `CHECKOUT.ORDER.APPROVED` fires
42	  // before the money moves — fulfilling on it would be exactly the "browser
43	  // signal, not a payment signal" mistake this codebase's Stripe fulfilment
44	  // comments document at length. `PAYMENT.CAPTURE.COMPLETED` is the money-moved
45	  // event; its resource is the CAPTURE, so the order id is recovered from
46	  // `supplementary_data.related_ids.order_id` (PayPal's documented shape) rather
47	  // than assumed to be `resource.id`.
48	  if (event.event_type === "PAYMENT.CAPTURE.COMPLETED") {
49	    const orderId = event.resource?.supplementary_data?.related_ids?.order_id;
50	    if (!orderId) {
51	      console.error("[paypal-webhook] capture event carried no order id", event.resource?.id);
52	      return NextResponse.json({ received: true });
53	    }
54	    try {
55	      // Re-derive the pendingId the same way the client-driven capture does: the
56	      // order's own custom_id (set at creation time in openPayPal). A defence-in-
57	      // depth re-read from PayPal itself, never trusting the webhook payload's own
58	      // (unsigned-at-this-layer) resource fields for anything but the order id.
59	      const order = await getPayPalOrder(orderId);
60	      const pendingId = order.purchase_units?.[0]?.custom_id;
61	      if (!pendingId) {
62	        console.error("[paypal-webhook] order carried no custom_id", orderId);
63	        return NextResponse.json({ received: true });
64	      }
65	      const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
66	      if (!row) {
67	        console.error("[paypal-webhook] no PendingExternalPayment for", pendingId);
68	        return NextResponse.json({ received: true });
69	      }
70	      // Closed-tab backstop for the vault save too — mirrors the same
71	      // best-effort, non-fatal write captureExternalPayPalOrder does for the
72	      // client-driven path (lib/actions-payment-providers.ts).
73	      const vault = vaultInfoFromCapture(order);
74	      if (vault) {
75	        await db.user
76	          .update({ where: { id: row.userId }, data: { paypalVaultId: vault.vaultId, paypalPayerEmail: vault.payerEmail } })
77	          .catch((e) => console.error("[paypal-webhook] could not record vaulted PayPal method", e));
78	      }
79	      await fulfilExternalPayment({ provider: "paypal", externalId: orderId, pendingId, base: process.env.APP_URL ?? "" });
80	    } catch (e) {
81	      // Errors are swallowed deliberately, exactly like the Stripe webhook: a
82	      // non-2xx here makes PayPal retry, and the failure is already recorded on
83	      // the FulfilledSession row and surfaced to the customer via notifyStalled.
84	      console.error("[paypal-webhook] fulfil failed", orderId, e);
85	    }
86	  }
87	
88	  return NextResponse.json({ received: true });
89	}
